table ip nat {
  chain pre {
    type nat hook prerouting priority -100;
    iifname "v1310-rt-net" ip daddr 192.0.2.50 dnat to 10.131.1.10       # entrada 1:1 (gateway de Internet)
  }
  chain post {
    type nat hook postrouting priority 100;
    oifname "v1310-rt-net" ip saddr 10.131.1.10 snat to 192.0.2.50       # salida 1:1 del web
    oifname "v1310-rt-net" ip saddr 10.131.2.0/24 masquerade             # salida compartida (gateway NAT)
  }
}
table ip filter {
  chain forward {
    type filter hook forward priority 0; policy drop;
    ct state established,related accept
    iifname "v1310-rt-net" ct status dnat accept     # de afuera solo entra lo que tiene traducción
    iifname "v1310-rt-pub" accept
    iifname "v1310-rt-priv" accept
  }
}

table inet sg {
  chain entrada {
    type filter hook input priority 0; policy drop;
    iifname "lo" accept
    ct state established,related accept              # con estado: la vuelta entra sola
    ip saddr 10.131.1.0/24 tcp dport 5432 accept     # solo la subred pública, solo el puerto 5432
  }
}

