// Costo mensual de NAT gateway zonal en sa-east-1, precios de lista al 16-11-2026 (USD).
const HORA = 0.093, POR_GB = 0.093, IPV4_HORA = 0.005, HORAS_MES = 730; // 730 h: un mes promedio, supuesto mío
function nat(zonas, gbProcesados) {
  const horas = zonas * HORA * HORAS_MES;
  const datos = gbProcesados * POR_GB;
  const ip = zonas * IPV4_HORA * HORAS_MES; // cada NAT gateway público lleva una IP elástica
  return { horas, datos, ip, total: horas + datos + ip };
}
for (const [zonas, gb] of [[1, 0], [1, 500], [3, 1500]]) {
  const c = nat(zonas, gb);
  console.log(`${zonas} NAT, ${String(gb).padStart(4)} GB: horas ${c.horas.toFixed(2)} + datos ${c.datos.toFixed(2)} + IPv4 ${c.ip.toFixed(2)} = ${c.total.toFixed(2)}`);
}
